def solve(grid, start, goal):
    n_rows, n_cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] != '.' or grid[goal[0]][goal[1]] != '.':
        return []
    if start == goal:
        return [start]

    def guess(p):
        return abs(p[0] - goal[0]) + abs(p[1] - goal[1])

    tick = 0
    pool = [(guess(start), 0, tick, start)]
    cost = {start: 0}
    back = {}
    done = set()
    while pool:
        _, spent, _, cur = heapq.heappop(pool)
        if cur in done:
            continue
        if cur == goal:
            seq = [cur]
            while seq[-1] in back:
                seq.append(back[seq[-1]])
            return seq[::-1]
        done.add(cur)
        r, c = cur
        for q in ((r, c + 1), (r + 1, c), (r, c - 1), (r - 1, c)):
            if 0 <= q[0] < n_rows and 0 <= q[1] < n_cols and grid[q[0]][q[1]] == '.':
                g2 = spent + 1
                if g2 < cost.get(q, 1 << 30):
                    cost[q] = g2
                    back[q] = cur
                    tick += 1
                    heapq.heappush(pool, (g2 + guess(q), g2, tick, q))
    return []

import sys


def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if grid[start[0]][start[1]] != '.' or grid[goal[0]][goal[1]] != '.':
        return []
    sys.setrecursionlimit(max(10000, rows * cols * 4))
    seen = set()
    trail = []

    def go(r, c):
        seen.add((r, c))
        trail.append((r, c))
        if (r, c) == goal:
            return True
        options = [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]
        options.sort(key=lambda p: abs(p[0] - goal[0]) + abs(p[1] - goal[1]))
        for nr, nc in options:
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in seen:
                if go(nr, nc):
                    return True
        trail.pop()
        return False

    return list(trail) if go(start[0], start[1]) else []

